import{_ as r,a0 as u,w as s,s as i,ao as n,I as p,a1 as o,A as e,x as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何使用Vault安全的存儲密碼和API密鑰 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用Vault安全的存儲密碼和API密鑰 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用Vault安全的存儲密碼和API密鑰 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用Vault安全的存儲密碼和API密鑰 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150506 How to Securely Store Passwords and Api Keys Using Vault","title":"如何使用Vault安全的存儲密碼和API密鑰","tag":"201505","desc":""},"relativePath":"201505/20150506 How to Securely Store Passwords and Api Keys Using Vault.md","filePath":"[post].md"}'),d={name:"201505/20150506 How to Securely Store Passwords and Api Keys Using Vault.md"};function g(V,t,m,h,S,b){const a=u("Link");return s(),i("div",null,[t[19]||(t[19]=n('<h1 id="如何使用vault安全的存儲密碼和api密鑰" tabindex="-1">如何使用Vault安全的存儲密碼和API密鑰 <a class="header-anchor" href="#如何使用vault安全的存儲密碼和api密鑰" aria-label="Permalink to “如何使用Vault安全的存儲密碼和API密鑰”">​</a></h1><p>Vault是用來安全的獲取秘密信息的工具，它可以保存密碼、API密鑰、證書等信息。Vault提供了一個統一的接口來訪問秘密信息，其具有健壯的訪問控制機制和豐富的事件日誌。</p><p>對關鍵信息的授權訪問是一個困難的問題，尤其是當有許多用户角色，並且用户請求不同的關鍵信息時，例如用不同權限登錄資料庫的登錄配置，用於外部服務的API密鑰，SOA通信的證書等。當保密信息由不同的平台進行管理，並使用一些自定義的配置時，情況變得更糟，因此，安全的存儲、管理審計日誌幾乎是不可能的。但Vault為這種複雜情況提供了一個解決方案。</p><h3 id="突出特點" tabindex="-1">突出特點 <a class="header-anchor" href="#突出特點" aria-label="Permalink to “突出特點”">​</a></h3><p><strong>數據加密</strong>：Vault能夠在不存儲數據的情況下對數據進行加密、解密。開發者們便可以存儲加密後的數據而無需開發自己的加密技術，Vault還允許安全團隊自定義安全參數。</p><p><strong>安全密碼存儲</strong>：Vault在將秘密信息（API密鑰、密碼、證書）存儲到持久化存儲之前對數據進行加密。因此，如果有人偶爾拿到了存儲的數據，這也沒有任何意義，除非加密後的信息能被解密。</p><p><strong>動態密碼</strong>：Vault可以隨時為AWS、SQL資料庫等類似的系統產生密碼。比如，如果應用需要訪問AWS S3 桶，它向Vault請求AWS密鑰對，Vault將給出帶有租期的所需秘密信息。一旦租用期過期，這個秘密信息就不再存儲。</p><p><strong>租賃和更新</strong>：Vault給出的秘密信息帶有租期，一旦租用期過期，它便立刻收回秘密信息，如果應用仍需要該秘密信息，則可以通過API更新租用期。</p><p><strong>撤銷</strong>：在租用期到期之前，Vault可以撤銷一個秘密信息或者一個秘密信息樹。</p><h3 id="安裝vault" tabindex="-1">安裝Vault <a class="header-anchor" href="#安裝vault" aria-label="Permalink to “安裝Vault”">​</a></h3><p>有兩種方式來安裝使用Vault。</p><p><strong>1. 預編譯的Vault二進制</strong> 能用於所有的Linux發行版，下載地址如下，下載之後，解壓並將它放在系統PATH路徑下，以方便調用。</p>',12)),p("ul",null,[p("li",null,[o(a,{href:"https://dl.bintray.com/mitchellh/vault/vault_0.1.0_linux_386.zip"},{default:e(()=>[...t[0]||(t[0]=[l("下載預編譯的二進制 Vault (32-bit)",-1)])]),_:1})]),p("li",null,[o(a,{href:"https://dl.bintray.com/mitchellh/vault/vault_0.1.0_linux_amd64.zip"},{default:e(()=>[...t[1]||(t[1]=[l("下載預編譯的二進制 Vault (64-bit)",-1)])]),_:1})]),p("li",null,[o(a,{href:"https://dl.bintray.com/mitchellh/vault/vault_0.1.0_linux_arm.zip"},{default:e(()=>[...t[2]||(t[2]=[l("下載預編譯的二進制 Vault (ARM)",-1)])]),_:1})])]),t[20]||(t[20]=n(`<p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/wget-binary.png" alt="wget binary"></p><p><em>下載相應的預編譯的Vault二進制版本。</em></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/unzip.png" alt="vault"></p><p><em>解壓下載到本地的二進制版本。</em></p><p>祝賀你！您現在可以使用Vault了。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/vault.png" alt=""></p><p><strong>2. 從源代碼編譯</strong>是另一種在系統中安裝Vault的方式。在安裝Vault之前需要安裝GO和GIT。</p><p>在 <strong>Redhat系統中安裝GO</strong> 使用下面的指令：</p><pre><code>sudo yum install go
</code></pre><p>在 <strong>Debin系統中安裝GO</strong> 使用下面的指令：</p><pre><code>sudo apt-get install golang
</code></pre><p>或者</p><pre><code>sudo add-apt-repository ppa:gophers/go

sudo apt-get update

sudo apt-get install golang-stable
</code></pre><p>在 <strong>Redhat系統中安裝GIT</strong> 使用下面的命令：</p><pre><code>sudo yum install git
</code></pre><p>在 <strong>Debian系統中安裝GIT</strong> 使用下面的命令：</p><pre><code>sudo apt-get install git
</code></pre><p>一旦GO和GIT都已被安裝好，我們便可以開始從源碼編譯安裝Vault。</p><blockquote><p>將下列的Vault倉庫拷貝至GOPATH</p></blockquote><pre><code>https://github.com/hashicorp/vault
</code></pre><blockquote><p>測試下面的文件是否存在，如果它不存在，那麼Vault沒有被克隆到合適的路徑。</p></blockquote><pre><code>$GOPATH/src/github.com/hashicorp/vault/main.go
</code></pre><blockquote><p>執行下面的指令來編譯Vault，並將二進制文件放到系統bin目錄下。</p></blockquote><pre><code>make dev
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/installation4.png" alt="path"></p><h3 id="一份vault入門教程" tabindex="-1">一份Vault入門教程 <a class="header-anchor" href="#一份vault入門教程" aria-label="Permalink to “一份Vault入門教程”">​</a></h3><p>我們已經編制了一份Vault的官方交互式教程，並帶有它在SSH上的輸出信息。</p><p><strong>概述</strong></p><p>這份教程包括下列步驟：</p><ul><li>初始化並啓封您的Vault</li><li>在Vault中對您的請求授權</li><li>讀寫秘密信息</li><li>密封您的Vault</li></ul><h4 id="初始化您的vault" tabindex="-1"><strong>初始化您的Vault</strong> <a class="header-anchor" href="#初始化您的vault" aria-label="Permalink to “初始化您的Vault”">​</a></h4><p>首先，我們需要為您初始化一個Vault的工作實例。在初始化過程中，您可以配置Vault的密封行為。簡單起見，現在使用一個啓封密鑰來初始化Vault，命令如下：</p><pre><code>vault init -key-shares=1 -key-threshold=1
</code></pre><p>您會注意到Vault在這裏輸出了幾個密鑰。不要清除您的終端，這些密鑰在後面的步驟中會使用到。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Initializing-SSH.png" alt="Initializing SSH"></p><h4 id="啓封您的vault" tabindex="-1"><strong>啓封您的Vault</strong> <a class="header-anchor" href="#啓封您的vault" aria-label="Permalink to “啓封您的Vault”">​</a></h4><p>當一個Vault服務器啓動時，它是密封的狀態。在這種狀態下，Vault被配置為知道物理存儲在哪裏及如何存取它，但不知道如何對其進行解密。Vault使用加密密鑰來加密數據。這個密鑰由&quot;主密鑰&quot;加密，主密鑰不保存。解密主密鑰需要入口密鑰。在這個例子中，我們使用了一個入口密鑰來解密這個主密鑰。</p><pre><code>vault unseal &lt;key 1&gt;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Unsealing-SSH.png" alt="Unsealing SSH"></p><p>####<strong>為您的請求授權</strong></p><p>在執行任何操作之前，連接的客户端必須是被授權的。授權的過程是檢驗一個人或者機器是否如其所申明的那樣具有正確的身份。這個身份用在向Vault發送請求時。為簡單起見，我們將使用在步驟2中生成的root令牌，這個信息可以回滾終端屏幕看到。使用一個客户端令牌進行授權：</p><pre><code>vault auth &lt;root token&gt;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Authorize-SSH.png" alt="Authorize SSH"></p><p>####<strong>讀寫保密信息</strong></p><p>現在Vault已經被設置妥當，我們可以開始讀寫默認掛載的秘密後端裏面的秘密信息了。寫在Vault中的秘密信息首先被加密，然後被寫入後端存儲中。後端存儲機制絕不會看到未加密的信息，並且也沒有在Vault之外解密的需要。</p><pre><code>vault write secret/hello value=world
</code></pre><p>當然，您接下來便可以讀這個保密信息了：</p><pre><code>vault read secret/hello
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/RW_SSH.png" alt="RW_SSH"></p><p>####<strong>密封您的Vault</strong></p><p>還有一個用I來密封Vault的API。它將丟掉現在的加密密鑰並需要另一個啓封過程來恢復它。密封僅需要一個擁有root權限的操作者。這是一種罕見的&quot;打破玻璃過程&quot;的典型部分。</p><p>這種方式中，如果檢測到一個入侵，Vault數據將會立刻被鎖住，以便最小化損失。如果不能訪問到主密鑰碎片的話，就不能再次獲取數據。</p><pre><code>vault seal
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Seal-Vault-SSH.png" alt="Seal Vault SSH"></p><p>這便是入門教程的結尾。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3>`,56)),p("p",null,[t[4]||(t[4]=l("Vault是一個非常有用的應用，它提供了一個可靠且安全的存儲關鍵信息的方式。另外，它在存儲前加密關鍵信息、審計日誌維護、以租期的方式獲取秘密信息，且一旦租用期過期它將立刻收回秘密信息。Vault是平台無關的，並且可以免費下載和安裝。要發掘Vault的更多信息，請訪問其",-1)),o(a,{href:"https://vaultproject.io/"},{default:e(()=>[...t[3]||(t[3]=[l("官方網站",-1)])]),_:1}),t[5]||(t[5]=l("。",-1))]),t[21]||(t[21]=p("hr",null,null,-1)),p("p",null,[t[7]||(t[7]=l("via: ",-1)),o(a,{href:"http://linoxide.com/how-tos/secure-secret-store-vault/"},{default:e(()=>[...t[6]||(t[6]=[l("http://linoxide.com/how-tos/secure-secret-store-vault/",-1)])]),_:1})]),p("p",null,[t[11]||(t[11]=l("作者：",-1)),o(a,{href:"http://linoxide.com/author/arunrz/"},{default:e(()=>[...t[8]||(t[8]=[l("Aun Raza",-1)])]),_:1}),t[12]||(t[12]=l(" 譯者：",-1)),o(a,{href:"https://github.com/wwy-hust"},{default:e(()=>[...t[9]||(t[9]=[l("wwy-hust",-1)])]),_:1}),t[13]||(t[13]=l(" 校對：",-1)),o(a,{href:"https://github.com/wxy"},{default:e(()=>[...t[10]||(t[10]=[l("wxy",-1)])]),_:1})]),p("p",null,[t[16]||(t[16]=l("本文由 ",-1)),o(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[14]||(t[14]=[l("LCTT",-1)])]),_:1}),t[17]||(t[17]=l(" 原創翻譯，",-1)),o(a,{href:"https://linux.cn/"},{default:e(()=>[...t[15]||(t[15]=[l("Linux中國",-1)])]),_:1}),t[18]||(t[18]=l(" 榮譽推出",-1))])])}const T=r(d,[["render",g]]);export{x as __pageData,T as default};
